```java
import java.util.ArrayList;
import java.util.List;
public class CorrelationCoefficient {
    public static void main(String[] args) {
        // Data from the article
        double[] airPollutionLevels = {15.3, 16.5, 18.2, 20.1, 21.3, 23.5, 25.6, 27.8, 29.7, 31.5};
        double[] mentalHealthOutcomes = {7.2, 6.8, 6.5, 6.1, 5.8, 5.4, 5.1, 4.7, 4.4, 4.0};
        // Calculate the mean of each dataset
        double airPollutionMean = calculateMean(airPollutionLevels);
        double mentalHealthMean = calculateMean(mentalHealthOutcomes);
        // Calculate the standard deviation of each dataset
        double airPollutionSD = calculateStandardDeviation(airPollutionLevels, airPollutionMean);
        double mentalHealthSD = calculateStandardDeviation(mentalHealthOutcomes, mentalHealthMean);
        // Calculate the correlation coefficient
        double correlationCoefficient = calculateCorrelationCoefficient(airPollutionLevels, mentalHealthOutcomes, airPollutionMean, mentalHealthMean, airPollutionSD, mentalHealthSD);
        System.out.println("Correlation coefficient: " + correlationCoefficient);
    }
    private static double calculateMean(double[] data) {
        double sum = 0;
        for (double value : data) {
            sum += value;
        }
        return sum / data.length;
    }
    private static double calculateStandardDeviation(double[] data, double mean) {
        double sum = 0;
        for (double value : data) {
            sum += Math.pow(value - mean, 2);
        }
        return Math.sqrt(sum / (data.length - 1));
    }
    private static double calculateCorrelationCoefficient(double[] x, double[] y, double xMean, double yMean, double xSD, double ySD) {
        double sum = 0;
        for (int i = 0; i < x.length; i++) {
            sum += (x[i] - xMean) * (y[i] - yMean);
        }
        return sum / ((x.length - 1) * xSD * ySD);
    }
}
```
