#include <iostream>
#include <vector>
#include <tuple>
#include <algorithm>
bool compareFruits(const std::tuple<std::string, std::string, double>& fruit1, const std::tuple<std::string, std::string, double>& fruit2) {
    // Compare fruits based on color first
    if (std::get<1>(fruit1) != std::get<1>(fruit2)) {
        return std::get<1>(fruit1) < std::get<1>(fruit2);
    }
    // If color is the same, compare based on price
