// Evaporation
def evaporation(temperature: Double, waterSurfaceArea: Double, humidity: Double): Double = {
  val evaporationRate = 0.0001 // constant for evaporation rate
  val vaporPressure = humidity * 0.067 // calculating vapor pressure
  val saturationVaporPressure = 0.611 * math.exp((17.27 * temperature) / (temperature + 237.3)) // calculating saturation vapor pressure
  val saturationHumidity = vaporPressure / saturationVaporPressure // calculating saturation humidity
  val evaporationAmount = evaporationRate * waterSurfaceArea * (saturationHumidity - humidity) // calculating evaporation amount
  evaporationAmount
}
// Condensation
def condensation(temperature: Double, humidity: Double): Double = {
  val dewPoint = (234.67 * math.log(humidity / 100) + ((17.67 * temperature) / (243.5 + temperature))) / (17.67 - math.log(humidity / 100) - ((17.67 * temperature) / (243.5 + temperature))) // calculating dew point
  val condensationAmount = humidity * 0.067 - 0.067 * math.exp((17.27 * dewPoint) / (dewPoint + 237.3)) // calculating condensation amount
  condensationAmount
}
// Precipitation
def precipitation(humidity: Double, temperature: Double, airPressure: Double): Double = {
  val saturationVaporPressure = 0.611 * math.exp((17.27 * temperature) / (temperature + 237.3)) // calculating saturation vapor pressure
  val vaporPressure = humidity * saturationVaporPressure // calculating vapor pressure
  val cloudHeight = (airPressure - vaporPressure) * 100 / (9.8 * 1000) // calculating cloud height
  val precipitationAmount = if (cloudHeight > 2000) cloudHeight / 1000 else 0 // calculating precipitation amount
  precipitationAmount
}
// Groundwater Flow
def groundwaterFlow(porosity: Double, permeability: Double, hydraulicHead: Double, distance: Double): Double = {
  val groundwaterVelocity = (porosity * permeability * hydraulicHead) / distance // calculating groundwater velocity
  val groundwaterFlowRate = groundwaterVelocity * 1000 * 60 * 60 * 24 // calculating groundwater flow rate
  groundwaterFlowRate
}
