Here is some sample C# code that demonstrates how to classify the given sentence "80% of survey participants utilize public transportation" as either descriptive or analytical:
```
using System;
using System.Collections.Generic;
using System.Linq;
using System.Text;
using System.Threading.Tasks;
using Microsoft.ML;
using Microsoft.ML.Data;
namespace SentenceClassification
{
    class Program
    {
        static void Main(string[] args)
        {
            // Create a new MLContext
            MLContext mlContext = new MLContext();
            // Define the data schema
            var data = mlContext.Data.LoadFromEnumerable(new List<Sentence>
            {
                new Sentence { Text = "80% of survey participants utilize public transportation" }
            });
            // Define the data preprocessing pipeline
            var preprocessingPipeline = mlContext.Transforms.Text
                .TokenizeIntoWords("Words", "Text")
                .Append(mlContext.Transforms.Text
                    .FeaturizeText("Features", "Words"));
            // Load the pre-trained model
