```go
package main
import (
    "encoding/json"
    "fmt"
    "io/ioutil"
    "net/http"
)
func main() {
    // Set the API endpoint and parameters
    endpoint := "https://api.nasa.gov/planetary/earth/assets"
    apiKey := "YOUR_API_KEY"
    lat := "37.7749"
    lon := "-122.4194"
    begin := "2019-01-01"
    end := "2020-12-31"
    // Build the API request URL
    url := fmt.Sprintf("%s?lon=%s&lat=%s&begin=%s&end=%s&api_key=%s",
        endpoint, lon, lat, begin, end, apiKey)
    // Send the API request and parse the response
    resp, err := http.Get(url)
    if err != nil {
        fmt.Println("Error sending API request:", err)
        return
    }
    defer resp.Body.Close()
    body, err := ioutil.ReadAll(resp.Body)
    if err != nil {
        fmt.Println("Error reading API response:", err)
        return
    }
    var data []struct {
        Date         string  `json:"date"`
        Tmax         float64 `json:"tmax"`
        Tmin         float64 `json:"tmin"`
        Precipitation float64 `json:"pr"`
        CO2          float64 `json:"co2"`
    }
    err = json.Unmarshal(body, &data)
    if err != nil {
        fmt.Println("Error parsing API response:", err)
        return
    }
    // Print the temperature, precipitation, and CO2 data
    for _, d := range data {
        fmt.Printf("Date: %s\n", d.Date)
        fmt.Printf("Max Temperature: %.2f°C\n", d.Tmax)
        fmt.Printf("Min Temperature: %.2f°C\n", d.Tmin)
