To make the sentence more active, we can change the subject of the sentence to the person or thing performing the action. In this case, we can change "the house" to "my father". The modified sentence would be "My father rearranged the house."
Here's a JavaScript function that detects passive voice sentences in a given text and suggests active voice alternatives:
```
function detectPassiveVoice(text) {
  const sentences = text.split('. '); // split text into sentences
  const passiveVoiceSentences = [];

  for (let i = 0; i < sentences.length; i++) {
    const words = sentences[i].split(' ');
    if (words[words.length - 2] === 'by') { // check if sentence ends with "by"
      passiveVoiceSentences.push(sentences[i]);
    }
  }

  // suggest active voice alternatives for each passive voice sentence
  const suggestions = passiveVoiceSentences.map(sentence => {
    const words = sentence.split(' ');
    const passiveVerb = words[words.length - 3];
    const activeVerb = getActiveVerb(passiveVerb);
    const subject = words[words.indexOf('by') - 1];
    const activeSentence = `${subject} ${activeVerb} ${words.slice(0, words.indexOf('by') - 1).join(' ')}.`;
    return activeSentence;
  });

  return suggestions;
}
function getActiveVerb(passiveVerb) {
  // add more verb conversions as needed
  switch (passiveVerb) {
    case 'was rearranged':
      return 'rearranged';
    case 'was built':
      return 'built';
    default:
      return passiveVerb;
  }
}
```
To use this function, simply pass in a string of text as an argument:
```
const text = "The house was rearranged by my father. The cake was baked by my sister. The book was written by the author.";
const suggestions = detectPassiveVoice(text);
console.log(suggestions); // ["My father rearranged the house.", "My sister baked the cake.", "The author wrote the book."]
```
Note that this function is not foolproof and may not catch all instances of passive voice. It also assumes that the subject performing the action comes before the verb in an active voice sentence.

