How can the sentence "I worked hard assembling the furniture" be restated using the formula X + present participle phrase, where X is the subject of the sentence?
[R code]
library(openNLP)
library(NLP)
tagPOS <- function(sent){
  sent_token_annotator <- Maxent_Sent_Token_Annotator()
  word_token_annotator <- Maxent_Word_Token_Annotator()
  pos_tag_annotator <- Maxent_POS_Tag_Annotator()

  sent_annots <- NLP::annotate(sent, list(sent_token_annotator, word_token_annotator))
  pos_annots <- NLP::annotate(sent, pos_tag_annotator, sent_annots)
  pos_tags <- unlist(lapply(pos_annots$POS.Tags, `[[`, "POS"))
  return(pos_tags)
}
getPresentParticiple <- function(text){
  text <- gsub("\\.", " ", text)
  text <- gsub(",", " ", text)
  text <- gsub("\\?", " ", text)
  text <- gsub("\\!", " ", text)
  text <- gsub("  ", " ", text)
  sentences <- as.list(strsplit(text, "\\. |\\? |\\! |\\n"))

  verb <- "assemble"
  present_participle <- paste0(verb, "ing")

  for (sent in sentences){
    if (length(sent) > 0){
      pos_tags <- tagPOS(sent)
      for (i in 1:length(pos_tags)){
        if (pos_tags[i] == "VBD" || pos_tags[i] == "VBN"){
          if (sent[i] == verb){
            sent[i] <- present_participle
          }
        }
      }
      print(paste(sent, collapse=" "))
    }
  }
}
getPresentParticiple("I worked hard assembling the furniture")

