How can I dynamically generate a table in C# using data from a SQL Server database? Can you provide an example of code that retrieves data from a database and populates a table with it?
Assuming I have a database named "myDatabase" and a table named "myTable" with columns "id", "name", and "age", how can I use C# to retrieve all the rows from "myTable" and populate a table with the data?
Here is an example of C# code that does this:
using System;
using System.Data.SqlClient;
using System.Web.UI.WebControls;
protected void Page_Load(object sender, EventArgs e)
{
    string connectionString = "Data Source=myServerAddress;Initial Catalog=myDatabase;User ID=myUsername;Password=myPassword";
    string query = "SELECT id, name, age FROM myTable";

    using (SqlConnection connection = new SqlConnection(connectionString))
    {
        using (SqlCommand command = new SqlCommand(query, connection))
        {
            connection.Open();
            using (SqlDataReader reader = command.ExecuteReader())
            {
                while (reader.Read())
                {
                    TableRow row = new TableRow();
                    TableCell idCell = new TableCell();
                    TableCell nameCell = new TableCell();
                    TableCell ageCell = new TableCell();

                    idCell.Text = reader["id"].ToString();
                    nameCell.Text = reader["name"].ToString();
                    ageCell.Text = reader["age"].ToString();

                    row.Cells.Add(idCell);
                    row.Cells.Add(nameCell);
                    row.Cells.Add(ageCell);

                    myTable.Rows.Add(row);
                }
            }
            connection.Close();
        }
    }
}
This code connects to the "myDatabase" database using the specified connection string, retrieves all rows from the "myTable" table using the specified query, and then loops through the rows, populating a table (named "myTable") with the data. Each row in the table has three columns: "id", "name", and "age". The data is retrieved using a SqlDataReader, and each cell in the table is created using a TableCell object.

